{
  "title": "Cusco at an easy trot",
  "summary": "A gentle day around the old centre, with the terraces kept as the one longer outing and the rest close together.",
  "stops": [
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Kept as the must-do, and it is the only ride out, so the rest of the day stays snug in the centre."
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "A free, easy wander in the heart of town, perfect for photo lovers and thrifty souls."
    },
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "Local life and street food without spending much, and just a short stroll from the square."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch beside the market, easy on the wallet and kind to vegetarians."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A sweet little museum stop nearby, so nobody has to rush or ride far."
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner around the corner from the museum to keep the evening gentle and close."
    }
  ]
}
